-- e-Business Afrique : description détaillée (maintenance, continuité, évolutions de 4 applications en production)
UPDATE "experiences" SET
  "title_fr" = 'Développeur Full-Stack',
  "title_en" = 'Full-Stack Developer',
  "description_fr" = 'Chez e-Business Afrique (Lomé, Togo), entreprise de services du numérique, j''ai repris des applications en production pour en assurer la maintenance, la continuité et l''évolution : corrections issues des recettes clients (UAT), refactorisation du code, sécurisation et scripts de déploiement. NSIA Togo (nsiadirect.tg) : API Laravel de l''assurance en ligne utilisée par l''application mobile, avec centralisation du calcul des tarifs (auto, moto, habitation, voyage), paiement mobile money SEMOA, attestations et factures PDF envoyées par e-mail et documentation de l''API. Base Réglementation (Laravel, Nuxt) : plateforme de suivi réglementaire de projets de recherche, avec droits d''accès par rôles, identifiants UUID, imports et exports Excel/PDF, alertes e-mail et refonte du manuel réglementaire. Base Budget (Laravel) : gestion multi-sites des budgets et des dépenses, avec soldes en temps réel et blocage des dépassements. Également : souscription d''assurance voyage en ligne pour NSIA Bénin.',
  "description_en" = 'At e-Business Afrique (Lomé, Togo), a digital services company, I took over production applications to ensure their maintenance, continuity and growth: fixes from client acceptance testing (UAT), code refactoring, security hardening and deployment scripts. NSIA Togo (nsiadirect.tg): Laravel API behind the online insurance mobile app, with centralised pricing (car, motorbike, home, travel), SEMOA mobile money payments, PDF certificates and invoices sent by email, and API documentation. Regulatory Database (Laravel, Nuxt): a regulatory tracking platform for research projects, with role-based access, UUID identifiers, Excel imports, Excel/PDF exports, email alerts and a redesigned regulatory handbook. Budget Database (Laravel): multi-site budget and expense management, with real-time balances and overspending prevention. Also: online travel insurance subscription for NSIA Benin.',
  "updated_at" = now()
WHERE "organization" = 'e-Business Afrique';
